class InterCourierChargeDialogController{constructor($scope,$mdDialog,$http,DispatchData,toastrService){this.$scope=$scope;this.$mdDialog=$mdDialog;this.$http=$http;this.DispatchData=DispatchData;this.toastrService=toastrService;this.data={fromCourierId:0,toCourierId:0,reference:"",zones:0,amount:0};this.courierChargeForm=$scope.courierChargeForm;this.fromCourierSearchText="";this.toCourierSearchText="";this.fromCourierSelectedItem=null;this.toCourierSelectedItem=null}async courierSearch(searchTerm){try{const url="/courier/AllActiveSearch";return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async submit(data){data.fromCourierId=this.fromCourierSelectedItem.id;data.toCourierId=this.toCourierSelectedItem.id;const url="courier/InterCourierCharge";this.$http.post(url,data,{headers:{"Content-Type":"application/json"}})}cancel(){this.$mdDialog.cancel()}}